async function initialisePartner(){const partner=partners.find(p=>p.id===selected);if(!partner)return;const specialism=profile?.specialism||'b2b_advisor';const{error:e}=await supabase.rpc('initialise_partner_onboarding',{p_partner:selected,p_specialism:specialism});if(e)return setError(e.message);toast('Partner onboarding initialised at 30% commission.');await load()}
